describe("httpTracesEndpoint", () => {
  it("appends /v1/traces only to endpoints without a path", () => {
    expect(httpTracesEndpoint("http://collector:4318")).toBe("http://collector:4318/v1/traces");
    expect(httpTracesEndpoint("http://collector:4318/")).toBe("http://collector:4318/v1/traces");
    expect(httpTracesEndpoint("https://h/api/otlp/v1/traces")).toBe("https://h/api/otlp/v1/traces");
    expect(httpTracesEndpoint("https://h/otlp")).toBe("https://h/otlp");
    expect(httpTracesEndpoint("https://h/?k=v")).toBe("https://h/?k=v");
    expect(httpTracesEndpoint("not a url")).toBe("not a url");
  });
});

describe("loadOtlpTls", () => {
  it("loads CA (inline + file), client certificate and key", () => {
    const tls = loadOtlpTls({
      caCertPem: "INLINE\n",
      caCertPath: pemFile("ca.pem", "FILE\n"),
      clientCertPath: pemFile("cert.pem", "CERT"),
      clientKeyPath: pemFile("key.pem", "KEY"),
      insecureSkipVerify: true,
    });
    expect(tls.ca?.toString()).toBe("INLINE\nFILE\n");
    expect(tls.cert?.toString()).toBe("CERT");
    expect(tls.key?.toString()).toBe("KEY");
    expect(tls.insecureSkipVerify).toBe(true);
    expect(loadOtlpTls({})).toEqual({ insecureSkipVerify: false });
    expect(loadOtlpTls({ caCertPem: "X" }).ca?.toString()).toBe("X");
  });

  it("an unreadable file is a ConfigError naming the field, not the path", () => {
    const missing = join(dir, "secret-name-missing.pem");
    for (const tls of [
      { caCertPath: missing },
      { clientCertPath: missing, clientKeyPath: missing },
    ]) {
      expect(() => loadOtlpTls(tls)).toThrow(ConfigError);
    }
    try {
      loadOtlpTls({ clientKeyPath: missing });
    } catch (err) {
      expect((err as Error).message).toBe(
        "tracing: cannot read tls.clientKeyPath (check the configured path)",
      );
      expect((err as Error).message).not.toContain("secret-name-missing");
    }
  });
});

describe("otlpGrpcCredentials", () => {
  it("plaintext for http://, TLS for https:// or TLS settings, undefined without either", () => {
    const none = { insecureSkipVerify: false };
    expect(otlpGrpcCredentials("http://c:4317", none)?._isSecure()).toBe(false);
    expect(otlpGrpcCredentials("HTTPS://c:4317", none)?._isSecure()).toBe(true);
    expect(otlpGrpcCredentials(undefined, none)).toBeUndefined();
    expect(otlpGrpcCredentials(undefined, { insecureSkipVerify: true })?._isSecure()).toBe(true);
    expect(otlpGrpcCredentials("https://c", { insecureSkipVerify: true })?._isSecure()).toBe(true);
  });
});

